    lookBack: () => {},
    lookForward: () => {},
    jumpToActive: () => {},
    skipCurrent: () => {},
    engineState: { status: 'idle' },
    setSelectedTask: () => {},
    ...value,
  };
  return (
    <KainBainContext.Provider value={base}>
      <NowPlayingBar />
    </KainBainContext.Provider>
  );
}


